function extract($, ctx) {
  const items = [];
  const seen = new Set();

  $('.menu[data-menu-index="0"] .menu-section').each((_, sectionEl) => {
    const $section = $(sectionEl);
    const sectionTitleEl = $section.find('.menu-section-title').first();
    const section = sectionTitleEl ? cleanText(sectionTitleEl.text()) : null;

    $section.find('.menu-items .menu-item').each((_, itemEl) => {
      const $item = $(itemEl);

      const titleEl = $item.find('.menu-item-title').first();
      if (!titleEl) return;
      let name = cleanText(titleEl.text());
      if (!name) return;

      // Clean leading numbering like "12. " and trailing allergen codes like "(1,7)"
      name = name.replace(/^\d+[\.\s]+/, '').replace(/\s*\([\d,\s]+\)\s*$/, '').trim();
      if (!name) return;

      const descEl = $item.find('.menu-item-description').first();
      const description = descEl ? cleanText(descEl.text()) : null;

      const priceEl = $item.find('.menu-item-price-top').first();
      const price = priceEl ? parsePrice(priceEl.text()) : null;

      const key = `${section}|${name}|${description || ''}|${price ?? ''}`;
      if (seen.has(key)) return;
      seen.add(key);

      items.push({ section, name, description, price });
    });
  });

  return items;
}
